% (1) fills the gap in def:improvement-uso (l.4291) and prop:auso-size (l.4655)
\begin{lemma}[The bottom-antipodal walk of an AUSO terminates]\label{lawsaudit:ba-terminates}
Let $s$ be the outmap of an AUSO of the $m$-cube and $u$ a vertex with $s(u)\ne\emptyset$. Then $u\oplus s(u)$ is reachable from $u$ along oriented edges. Consequently the bottom-antipodal walk strictly ascends the reachability order, visits pairwise distinct vertices, and terminates after at most $2^{m}-1$ steps.
\end{lemma}
\begin{proof}
Put $J:=s(u)$ and let $F$ be the face spanned by $u$ and $v:=u\oplus J$, whose direction set is $J$. The restriction $s_F(x):=s(x)\cap J$ satisfies the condition of \Cref{def:improvement-uso} inside $F$ and its digraph is a subdigraph of $s$'s, hence acyclic; so $s_F$ is an AUSO of $F$, and $s_F(u)=J$ makes $u$ its source. The coordinatewise complement $s'_F(x):=J\setminus s_F(x)$ leaves $(s_F(x)\oplus s_F(y))\cap(x\oplus y)$ unchanged, so $s'_F$ is again a unique sink orientation of $F$; it is the edge reversal of $s_F$, hence also acyclic. In a finite acyclic orientation, following outgoing edges from any vertex must stop, and it stops only at a vertex of empty outmap, which by the unique-sink property of $F$ is unique; so from every vertex of $F$ the sink of $s'_F$ is $s'_F$-reachable, and that sink is the $x$ with $s_F(x)=J$, namely $u$. Taking $x=v$ and reversing the path gives an $s$-path from $u$ to $v$. Acyclicity then makes $u<u\oplus s(u)$ strict, so the walk never repeats a vertex.
\end{proof}

% (2) repairs lem:max-tree (l.3879): read "a BALANCED rooted binary tree of $r-1$ Max vertices, of height $d:=\lceil\log_2r\rceil$"
\begin{remark}[The tree must be balanced]\label{lawsaudit:tree-unbalanced}
Without balance the conclusion fails already at $r=4$. Let $G$ be the one-player stopping SSG on $11$ vertices with $\Vmax=\{p,q,r\}$, $p\to(q,A_4)$, $q\to(r,A_3)$, $r\to(t_1,A_2)$, where $A_2,A_3,A_4$ are average gadgets of the constant values $\tfrac18,\tfrac14,\tfrac12$, and start at $p\mapsto A_4$, $q\mapsto A_3$, $r\mapsto A_2$. The four action values $1,\tfrac18,\tfrac14,\tfrac12$ never change and $d=\lceil\log_24\rceil=2$, yet the all-switches run is $\{r\},\{q\},\{p\}$ and after two rounds the root still holds $\tfrac12$, not the maximum $1$ (exact arithmetic). The induction in the proof of \Cref{lem:max-tree} is on the height of the tree, and only a balanced tree has height $\lceil\log_2r\rceil$.
\end{remark}

% (3) corrects the claim at l.3756 and completes prop:k1-family
\begin{proposition}[$K_n$ lies in the escape class]\label{lawsaudit:k1-escape}
For every $n\ge1$ the game $K_n$ of \Cref{prop:k1-family} carries the escape certificate of \Cref{def:survival} given by $\lambda:=\tfrac{19}{20}$ and
\[ x(x_i)=3,\quad x(m_i)=\tfrac{60}{19},\quad x(c_i)=\tfrac{1000}{361},\quad x(d_i)=\tfrac{40}{19},\quad x(e_i)=1\qquad(1\le i\le n). \]
Hence $x\ge\bbone$, $Sx\le\lambda x$ and $\kappa(x)=\tfrac{60}{19}$, all independent of $n$, so $\log_2(1/\lambda)$ and $\log_2\kappa(x)$ are constants and \Cref{thm:escape-class} decides \Cref{prob:main} on the family $(K_n)_{n\ge1}$ in polynomial time. In particular $K_n$ does \emph{not} escape every class of \Cref{sec:special}; what \Cref{prop:k1-family} shows is that it escapes the four classes it names.
\end{proposition}
\begin{proof}
$Sx(e_i)=\tfrac12(\hat x(t_1)+\hat x(t_0))=0\le\lambda$. $Sx(d_i)=\tfrac12(x(e_i)+\hat x(x_{i+1}))\le\tfrac12(1+3)=2=\tfrac{19}{20}\cdot\tfrac{40}{19}$, the case $i=n$ using $\hat x(t_1)=0$. $Sx(m_i)=\max(x(x_i),x(d_i))=3=\tfrac{19}{20}\cdot\tfrac{60}{19}$. $Sx(c_i)=\tfrac12(x(m_i)+x(d_i))=\tfrac{50}{19}=\tfrac{19}{20}\cdot\tfrac{1000}{361}$. $Sx(x_i)=\max(x(c_i),x(e_i))=\tfrac{1000}{361}<\tfrac{57}{20}=\tfrac{19}{20}\cdot3$. Verified in exact arithmetic for $n\le40$. By \Cref{lem:escape-rate} no certificate can do better than $\lambda^{\ast}(K_n)=2^{-1/3}$, the only cycle of $K_n$ being $x_i\to c_i\to m_i\to x_i$, of weight $\tfrac12$ over three steps.
\end{proof}

% (4) supplies prop:k1-family's value formula for all $n$
\begin{proof}[Values in \Cref{prop:k1-family}]
Write $V_i,M_i,C_i,D_i,E_i$ for $w^{\ast}$ at $x_i,m_i,c_i,d_i,e_i$ and $V_{n+1}:=1$. The equations $Tw^{\ast}=w^{\ast}$ read $E_i=\tfrac12$, $D_i=\tfrac12(E_i+V_{i+1})$, $M_i=\min(V_i,D_i)$, $C_i=\tfrac12(M_i+D_i)$, $V_i=\max(C_i,E_i)$. The vector $V_i=M_i=C_i=D_i=\tfrac12+2^{-(n-i+2)}$, $E_i=\tfrac12$ satisfies them, since $D_i=\tfrac12(\tfrac12+\tfrac12+2^{-(n-i+1)})=\tfrac12+2^{-(n-i+2)}$ and $\max(V_i,\tfrac12)=V_i$. As $K_n$ is stopping the fixed point of $T$ is unique (\Cref{thm:contraction}), so $w^{\ast}(x_1)=\tfrac12+2^{-(n+1)}$.
\end{proof}

